def kv(commands):
    store, out = {}, []
    for cmd in commands:
        op = cmd[0]
        if op == 'SET':
            store[cmd[1]] = cmd[2]
            out.append('OK')
        elif op == 'GET':
            out.append(store.get(cmd[1]))
        elif op == 'INCR':
            v = int(store.get(cmd[1], '0')) + 1
            store[cmd[1]] = str(v)
            out.append(v)
        elif op == 'DEL':
            out.append(1 if store.pop(cmd[1], None) is not None else 0)
    return out
